529	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
530	    @Override
531	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
532	        Owner owner = this.clinicService.findOwnerById(ownerId);
533	        if (owner != null) {
534	            Pet pet = owner.getPet(petId);
535	            if (pet != null) {
536	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
